from admissions_records import *

skills=['reading','writing','listening','speaking']
unknown={'satPolicy':'unknown','note':L('Academic entry is assessed against the applicant’s school qualification and course. This English policy does not establish a university-wide SAT/ACT requirement or exemption.','Академический допуск оценивается по школьной квалификации и программе кандидата. Языковая политика не устанавливает общеуниверситетскую обязательность или освобождение от SAT/ACT.')}
def src(url,en,ru):return S(url,L(en,ru),access='web-html-read')
def eng(min,band,variant='IELTS Academic'):
 return {'requirement':'required-unless-exempt','ielts':{'accepted':True,'variant':variant,'min':min,'sections':dict.fromkeys(skills,band),'role':'admission'}}
gaps=['Exact course-specific Fall 2027 applicability and academic requirements for the school qualification need confirmation; a general table is not a check of every degree.']

su='https://www.sussex.ac.uk/study/undergraduate/apply/international-qualifications/english-language-requirements'
sr=[]
for id,name,ru,score,band in [('standard','Standard','Стандартный',6,5.5),('high','High','Высокий',6.5,6),('advanced','Advanced','Продвинутый',7,6.5)]:
 e=eng(score,band,'IELTS Academic / Online; One Skill Retake accepted')
 e.update(note=L('The course page assigns Standard, High or Advanced. These levels are not merged into one university minimum. Medicine BMBS instead requires 7.5 overall/7.0 each. Tests normally valid for two years.','Страница программы назначает Standard, High либо Advanced. Эти уровни не объединяются в один минимум вуза. Для Medicine BMBS вместо них требуется 7,5 overall/7,0 каждая секция. Тест обычно действует два года.'),alternatives=L('TOEFL iBT including Home Edition, Cambridge, Duolingo, PTE Academic in person and specified SELT alternatives are accepted at the course’s level. Approved qualifications, published exemptions or pre-sessional completion can also satisfy English.','Принимаются TOEFL iBT, включая Home Edition, Cambridge, Duolingo, очный PTE Academic и указанные SELT на уровне программы. Также могут подойти одобренные квалификации, опубликованные освобождения либо завершение pre-sessional.'))
 sr.append(route(id=id,label=L('Course English level: '+name,'Уровень английского программы: '+ru),english=e,academic=unknown,sources=[src(su,'Sussex undergraduate course language levels','Sussex: языковые уровни бакалаврских программ')]))
record('university-of-sussex',sr,'Separated Standard, High and Advanced language bands; no single 6.0 cutoff is assigned to all degrees.',gaps)

gu='https://www.gre.ac.uk/international/support-and-help/courses'
ge=eng(6,5.5,'IELTS Academic / Online; One Skill Retake accepted')
ge.update(toefl={'accepted':True,'scales':[{'period':'legacy','min':72,'sections':{'reading':18,'listening':17,'speaking':20,'writing':17}},{'period':'post2026','min':4.5,'sections':dict.fromkeys(skills,4)}]},alternatives=L('For the 6.0 category: Duolingo 105 with each skill 95; PTE Academic in person 59 with each skill 51; Cambridge 169/162; ELLT 6/5; approved foundation English qualifications. TOEFL is in person only.','Для категории 6,0: Duolingo 105 с каждым навыком 95; очный PTE Academic 59 с каждым навыком 51; Cambridge 169/162; ELLT 6/5; одобренные языковые квалификации Foundation. TOEFL только очный.'),waiver=L('Specified GCSE/IGCSE, IB, country qualifications or eligible English-country/degree categories may satisfy English; the exact qualification and validity period must match the published table.','Могут подойти указанные GCSE/IGCSE, IB, национальные квалификации либо допустимые категории англоязычных стран/степеней; точная квалификация и срок должны соответствовать опубликованной таблице.'),note=L('General BA/BSc/BEng rule excludes listed Architecture, Criminology, English, nutrition, nursing, midwifery, social work and speech-therapy exceptions. A 5.5-equivalence table is not a direct-entry rule for all degrees.','Общее правило BA/BSc/BEng исключает перечисленные Architecture, Criminology, English, питание, сестринское дело, акушерство, социальную работу и логопедию. Таблица эквивалентов 5,5 не является правилом прямого приёма на все степени.'))
record('university-of-greenwich',[route(id='general-ba-bsc-beng',label=L('General BA/BSc/BEng — listed exceptions excluded','Общие BA/BSc/BEng — перечисленные исключения не включены'),english=ge,academic=unknown,sources=[src(gu,'Greenwich undergraduate language table and exceptions','Greenwich: языковая таблица бакалавриата и исключения')])],'Added exact general degree and alternative-test section minima without treating lower equivalence columns as direct entry.',gaps)

wu='https://www.westminster.ac.uk/study/english-language-requirements'
we=eng(6,5.5,'IELTS Academic / Online / UKVI; One Skill Retake accepted')
we.update(alternatives=L('Standard bachelor category: TOEFL in person 78 or new-scale 4 overall; legacy L/W17, R18, S20. MyBest accepted, Home Edition/ITP/Essentials/TOEIC not accepted. The source dates the scale change May 2025, so the test-date boundary is unresolved. PTE in person each 59; Duolingo 115 with each subscore 100.','Стандартный бакалавриат: очный TOEFL 78 либо новый общий 4; прежние L/W17, R18, S20. MyBest принимается, Home Edition/ITP/Essentials/TOEIC — нет. Источник датирует смену шкалы маем 2025, поэтому граница дат теста не прояснена. Очный PTE каждая секция 59; Duolingo 115 с каждым подбаллом 100.'),waiver=L('Specific GCSE/IGCSE, IB or approved country qualifications; eligible English-medium degree/TNE study and certain completed academic years, assessed individually. Work experience alone is insufficient; a generic MOI letter outside listed conditions is not accepted.','Определённые GCSE/IGCSE, IB либо одобренные национальные квалификации; подходящая англоязычная степень/TNE и некоторые завершённые учебные годы, с индивидуальной оценкой. Одного опыта работы недостаточно; обычное письмо MOI вне перечисленных условий не принимается.'),note=L('Published standard bachelor rule; some course pages require higher overall or section scores. Pre-sessional admission uses separate SELT rules.','Опубликованный стандарт бакалавриата; некоторые страницы программ требуют более высокие overall либо секции. Для pre-sessional отдельные правила SELT.'))
record('university-of-westminster',[route(id='standard-bachelor',english=we,academic=unknown,sources=[src(wu,'Westminster bachelor English tests, waivers and exceptions','Westminster: тесты английского, освобождения и исключения бакалавриата')])],'Separated standard bachelor minima from postgraduate scores and exposed the source’s TOEFL scale-date problem.',gaps)

cu='https://www.coventry.ac.uk/course-structure/ug/eec/computer-science-mscibsc-hons/?term=2027-28'
ce=eng(6,5.5,'IELTS; exact Academic test variant requires confirmation')
ce['note']=L('BSc Computer Science at Coventry campus, September 2027. A foundation option and pre-sessional preparation exist but do not share this direct-entry rule. CEFR B2 for a visa is not a substitute for the course’s IELTS condition.','BSc Computer Science кампуса Coventry, сентябрь 2027. Есть Foundation и pre-sessional, но это не то же правило прямого приёма. Визовый CEFR B2 не заменяет условие IELTS программы.')
record('coventry-university',[route(id='computer-science-bsc-2027',label=L('Computer Science BSc (Hons) — Coventry, September 2027','Computer Science BSc (Hons) — Coventry, сентябрь 2027'),programmeIds=['computer-science'],applicability={**cycle(L('September 2027','Сентябрь 2027'),[2027]),'intakes':['fall-2027']},english=ce,academic=unknown,sources=[src(cu,'Coventry Computer Science 2027/28 entry requirements','Coventry Computer Science: требования 2027/28'),src('https://www.coventry.ac.uk/international-students-hub/apply/english-requirements/','Coventry degree versus preparatory visa English rules','Coventry: языковые визовые правила степени и подготовки')])],'Anchored IELTS 6.0/5.5 to an actual 2027 Coventry-campus degree rather than a generic visa level.', ['Exact alternative tests, waiver eligibility and national school-qualification criteria for this degree require confirmation.'])
finish()
